import { readFile, readdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = path.join(root, "supabase", "migrations");
const outputFile = path.join(root, "supabase", "bootstrap.sql");

const files = (await readdir(migrationsDir))
  .filter((file) => file.endsWith(".sql"))
  .sort();

const parts = [
  "-- TickShow combined Supabase bootstrap.",
  "-- Generated by `npm run db:bundle`; edit migrations and regenerate instead of editing this file.",
  "-- Safe to re-run: all migrations use IF NOT EXISTS / IF EXISTS or CREATE OR REPLACE where needed.",
  "",
];

for (const file of files) {
  const sql = await readFile(path.join(migrationsDir, file), "utf8");
  parts.push(`-- ===== ${file} =====`, sql.trimEnd(), "");
}

await writeFile(outputFile, parts.join("\n"), "utf8");
console.log(`Wrote ${path.relative(root, outputFile)} from ${files.length} migrations.`);
